// ErrorPage.js
import React from "react";
import { Link } from "react-router-dom";

const ErrorPage = () => {
    return (
        <div className="container">
            <h2>❌ Sign Up Failed</h2>
            <p>There was a problem while trying to register. Please try again later.</p>
            <Link to="/signup">
                <button className="ui button blue">Go Back to Signup</button>
            </Link>
        </div>
    );
};

export default ErrorPage;
